import type { Player } from './index';

export const coach = 'Jesse Marsch';
export const squad: Player[] = [
  // Porteros
  { number: 1, name: 'Dayne St. Clair', position: 'GK', age: 28, club: 'Inter Miami', bio: {"es":"St. Clair, un gentil gigante fuera del campo, tiene un carácter diferente y, con 1,90 m, resulta intimidante para los atacantes. Armado con reflejos rápidos y manos fuertes, se convirtió en el segundo 'Wonderwall' del Minnesota United durante su estancia en el club; el primero fue la sección de pie en su campo. Después de ganar el premio al Portero del Año de la MLS en 2025, dijo: “Casi siento como si hubiera una pared detrás de mí y la pared en la línea, lo que significa que no va a entrar ningún balón”. The Wonderwall también tenía una canción tributo a Bon Jovi para él: \"Whoa, tiene un cabello fantástico / whoa-oh, Dayne St Clair / con sus manos, lo salvará, lo juro / woah-oh, Dayne St Clair\". Se mudó al Inter Miami para la temporada 2026, convirtiéndose en compañero de Lionel Messi. \"Cada vez que ese chico está en tu equipo, la expectativa es ganar y levantar trofeos\", dijo. “Tener esas expectativas y esa presión es un privilegio”.","en":"A gentle giant off the pitch, St. Clair is a different character on it and at 1.90m, he is an intimidating sight for attackers. Armed with quick reflexes and strong hands, he became Minnesota United’s second ‘Wonderwall’ during his time at the club – the first being the standing-room only section at their ground. After winning the MLS Goalkeeper of the Year award in 2025, he said: “I almost feel like there’s a wall behind me and the wall on the line that means no ball’s going to go in.” The Wonderwall had a Bon Jovi-based tribute song for him, too: “Whoa he’s got great hair / whoa-oh, Dayne St Clair / with his hands, he’ll save it I swear / woah-oh, Dayne St Clair.” He moved to Inter Miami for the 2026 season, becoming teammates with Lionel Messi. “Any time that guy's on your team, the expectation is to win and to lift trophies,” he said. “To have those expectations and that pressure is a privilege.”"}, special: "Gentle giant" },
  { number: 16, name: 'Maxime Crépeau', position: 'GK', age: 31, club: 'Orlando City', bio: {"es":"A menos de un mes de lo que se suponía sería su primer Mundial en 2022, Crépeau sufrió una desafortunada lesión en la pierna, que lo descartó del torneo y lo mantuvo fuera de acción durante casi un año. Si le preguntaras si cambiaría algo, diría que no. La lesión se produjo en una parada para salvar el partido en la final de la Copa MLS 2022 entre el LAFC de Crépeau y el Philadelphia Union, que el LAFC ganó. \"No se toman atajos [como portero]\", dijo más tarde. \"Hay que darlo todo, y yo lo hice. Así es como juego\". Crépeau, un portero más bajo, de 1,81 m de altura, ciertamente juega mucho más que su altura, ya que no tiene miedo de proteger su área y su red. Con pies rápidos y fuertes reflejos, le encanta jugar en los partidos más importantes, como lo demostró cuando ayudó a Canadá a llegar a las semifinales de la Copa América 2024. Habla francés, inglés y, debido a que la familia de su esposa es chilena, español, y a su pequeña hija le gusta mezclarlos. “A veces mi hija comienza una oración en francés, la termina en español y en el medio pone una o dos palabras en inglés”.","en":"Less than a month out from what was supposed to be his first World Cup in 2022, Crépeau suffered an unfortunate leg injury, one that ruled him out of the tournament and kept him out of action for almost a year. If you were to ask him if he’d change a thing, he’d say no. The injury came on a game-saving stop in the 2022 MLS Cup final between Crépeau’s LAFC and Philadelphia Union, which LAFC went on to win. \"You don't cut corners [as a keeper],” he said later. “You have to go all out, and I went all out. This is how I play.\" A smaller keeper at 1.81m tall, Crépeau certainly plays much bigger than his height, as he is unafraid to protect his box and his net. With his quick feet and strong reflexes, he loves playing in the biggest games, as he showed when he helped Canada reach the semi-finals of the 2024 Copa América. He speaks French, English and – due to his wife’s family being from Chile – Spanish, and his little daughter likes to mix it up. “Sometimes my daughter will start a sentence in French, will finish it in Spanish, and in the middle she'll put one or two words in English in there.”"}, special: "Multilinguist" },
  { number: 18, name: 'Owen Goodman', position: 'GK', age: 23, club: 'Crystal Palace', bio: {"es":"No hay duda del compromiso de Goodman con Canadá. El joven portero, que nació en Londres pero vivió en Ontario desde los cinco hasta los 13 años, contrató el año pasado a un abogado de inmigración para que le ayudara a conseguir un pasaporte canadiense, con la vista puesta en el Mundial. La perseverancia dio sus frutos, ya que aprobó su examen de ciudadanía y obtuvo un llamado a filas de alto nivel en Canadá. \"Una vez que tengo una cosa en mente, no hay nada que me detenga. Nadie se interpondrá en mi camino\", dijo al Athletic, después de haber jugado previamente para Inglaterra en el nivel juvenil y haber rechazado una propuesta de Nigeria mientras esperaba que se procesara la solicitud. Cuando fue así, dijo: \"Sentí un poco de escalofríos recorriendo mi columna... Estuve esperando tanto que empiezas a perder un poco de esperanza. Quería saltar de alegría\". Goodman, un tapón talentoso con una gran estructura, es un prospecto emocionante y se ha desarrollado cedido por Palace en AFC Wimbledon, Huddersfield y, más recientemente, Barnsley, y el siguiente paso probablemente sea un préstamo para el campeonato.","en":"There’s no doubting Goodman’s commitment to Canada. The young keeper, who was born in London but lived in Ontario from the age of five to 13, hired an immigration lawyer last year to help him get a Canadian passport, with one eye on the World Cup. The persistence paid off as he passed his citizenship test, and earned a senior Canada call-up. “Once I’ve got my mind on one thing, there’s nothing that’s going to stop me. No one’s going to get in my way,” he told the Athletic, having previously played for England at youth level and turned down an approach from Nigeria while he was waiting for the application to be processed. When it was, he said: “I had shivers go down my spine a little bit … I was waiting so long you start to lose a bit of hope. I wanted to jump for joy.” A talented shot stopper with a big frame, Goodman is an exciting prospect, and has developed on loan from Palace at AFC Wimbledon, Huddersfield and most recently Barnsley, with the next step likely to be a Championship loan."} },
  // Defensores
  { number: 2, name: 'Alistair Johnston', position: 'DF', age: 27, club: 'Celtic', bio: {"es":"Nacido en una familia amante del fútbol, ​​Johnston solía despertarse a las 4:30 a.m. los sábados por la mañana en Columbia Británica para ver partidos de la Premier League inglesa en vivo, y nunca ha perdido ese amor por el juego. Entusiasta, duro y lleno de liderazgo y pasión naturales, los fanáticos del Celtic lo aman por comprender lo que significa representar a su club, desde el día en que llegó en diciembre de 2022. Le dijo a The Guardian el año pasado: \"Veo lo que el club significa para la gente. Entiendo que si soy fanático de un club como este, ¿qué me gustaría ver de mis jugadores? Soy honesto con mi trabajo, a la defensiva me encantan las entradas, me encanta ser físico. Estoy un poco loco por el fútbol. Amo la ciudad. [Es] la pecera más grande de toda Europa. Todo el mundo sabe quién eres. No sabes si te aman o te odian, pero sabes quién eres, quizás fuera de un radio de 30 millas del centro de la ciudad de Glasgow. Un excelente pasador y un implacable defensor uno a uno, puede jugar en múltiples posiciones pero tiene todas las herramientas necesarias de un lateral moderno.","en":"Born into a football-loving family, Johnston used to wake up at 4.30am on Saturday mornings in British Columbia to watch English Premier League matches live, and has never lost that love for the game. Enthusiastic, hard-tackling and full of natural leadership and passion, he is loved by Celtic fans for understanding what it means to represent their club, ever since the day he arrived back in December 2022. He told the Guardian last year: “I see what the club means to people. I understand that if I’m a fan of a club like this, what would I like to see from my players? I’m honest with my work, defensively love a tackle, love being physical. I’m a bit football mad. I love the city. [It’s] the biggest fish bowl in all of Europe. Everyone knows who you are. You don’t know if they love you or hate you but you know they know who you are. I’m not famous outside of maybe a 30-mile radius of Glasgow city centre … but what a radius.” An excellent passer and relentless one-on-one defender, he can play in multiple positions but has all of the tools required of a modern full-back."}, special: "Loves a tackle" },
  { number: 3, name: 'Alfie Jones', position: 'DF', age: 28, club: 'Middlesbrough', bio: {"es":"Una charla informal en el vestuario con el extremo canadiense Liam Millar cuando ambos estaban juntos en Hull en la temporada 2024-2025 cambió la carrera de Jones. El defensa nacido en Bristol le mencionó a Millar que tenía una abuela canadiense, por lo que su compañero de club le señaló las posibilidades. Lo que siguió fue un período vertiginoso para Jones, quien pasó por el proceso para obtener la ciudadanía e hizo su debut en Canadá contra Venezuela en noviembre del año pasado. Un corpulento central de 1,90 m conocido por su agresividad, su habilidad con el balón y su destreza aérea, fue nombrado jugador del año del Hull en 2023 (elegido por el entonces entrenador Liam Rosenior) antes de unirse al Middlesbrough el año pasado. Jones tuvo una temporada interrumpida por lesiones, pero recuperó su agudeza a tiempo para ocupar su lugar en el equipo de este verano. \"Siento que hay una conexión allí, está en mi línea de sangre estar vinculado a Canadá, y soy un tipo muy emotivo\", dijo el año pasado. “Entonces, lo que me motiva es la idea de ponerme la camiseta canadiense y hacer lo mejor que pueda para representar al país”.","en":"A casual locker room chat with Canada winger Liam Millar when the pair were at Hull together in the 2024-2025 season proved career-changing for Jones. The Bristol-born defender mentioned to Millar that he had a Canadian grandmother, so his clubmate pointed out the possibilities. What followed was a whirlwind period for Jones, who went through the process to earn citizenship and made his Canada debut against Venezuela in November last year. A hulking 1.90m centre-back known for aggression, ball-playing skills and aerial prowess, he was named Hull’s player of the year in 2023 – chosen by then-manager Liam Rosenior – before joining Middlesbrough last year. Jones had an injury-disrupted season, but regained sharpness in time to take his place in this summer’s squad. “I feel there's a connection there, it's in my bloodline being linked to Canada, and I'm a very emotional guy,” he said last year. “So, the thought of putting on the Canadian shirt and just doing the best I can to represent the country is what drives me.”"} },
  { number: 4, name: 'Luc De Fougerolles', position: 'DF', age: 20, club: 'Fulham', bio: {"es":"En un momento del año pasado, De Fougerolles, cuyo padre nació en Montreal, tuvo más apariciones con Canadá que como profesional de club, prueba de la gran impresión que ha causado el joven en el panorama internacional. Con la tarea de intervenir mientras Canadá lidiaba con una serie de lesiones en 2023, inmediatamente se sintió como en casa, mostrando conciencia posicional y compostura con el balón. Nacido en Londres, De Fougerolles se unió a la academia del Fulham a los ocho años y firmó su primer contrato profesional en 2023, ganando el premio académico del año. Se unió al Dender de la Pro League belga en julio para continuar su desarrollo. “Conocer nuevos compañeros de equipo, vivir en un país diferente, todo ha sido completamente diferente para mí”, dijo el año pasado. \"Sólo conozco al Fulham. Cambiar eso, irme a vivir solo a Bélgica ha sido difícil, pero mis compañeros me lo han puesto fácil y ha sido un gran grupo. He disfrutado mucho mi estancia aquí\". Fue nombrado jugador joven del año de Canadá en 2025.","en":"At one stage last year De Fougerolles, whose dad was born in Montreal, had more appearances for Canada than he did as a club professional – evidence of what a big impression the youngster has made in the international setup. Tasked to step in as Canada dealt with a rash of injuries in 2023 he immediately looked at home, showing positional awareness and composure on the ball. Born in London, De Fougerolles joined Fulham’s academy aged eight, and signed his first professional deal in 2023, winning scholar of the year. He joined Belgian Pro League side Dender that July to continue his development. “Meeting new teammates, living in a different country, everything about it has been completely different for me,” he said last year. “I’ve only ever known Fulham. To change that around, to go and live alone in Belgium has been tough, but my teammates have made it easy and it’s been a great group. I’ve really enjoyed my time here.” He was named Canada’s young player of the year for 2025."} },
  { number: 5, name: 'Joel Waterman', position: 'DF', age: 30, club: 'Chicago Fire', bio: {"es":"Waterman hizo historia en 2020 como el primer jugador de la nueva Premier League canadiense en transferirse a un club de la MLS, cuando llegó al CF Montréal procedente del Cavalry FC. Esa fue una decisión astuta para Waterman, quien había estado jugando a nivel universitario canadiense en 2018 antes de unirse a Cavalry. Se ha convertido en un jugador importante para Montréal, convirtiéndose en uno de los capitanes del club durante sus últimas temporadas. Ex mediocampista, se siente cómodo con el balón pero también agresivo a la defensiva, lo que lo ha ayudado a convertirse en un habitual en la configuración nacional y en su nuevo club, Chicago Fire. Waterman también forma parte de una gran familia deportiva: está casado con Carli Grosso, hermana de la mediocampista canadiense Julia Grosso, quien está comprometida con la estrella del béisbol de los Astros de Houston, Jeremy Peña.","en":"Waterman made history in 2020 as the first player from the new Canadian Premier League to transfer to an MLS club, when he joined CF Montréal from Cavalry FC. That proved a shrewd decision for Waterman, who had been playing at the Canadian university level in 2018 before joining Cavalry. He has grown into an important player for Montréal, becoming one of the club’s captains during his last few seasons. A former midfielder, he is comfortable on the ball but also aggressive defensively, which has helped him become a regular in the national setup and for his new club, Chicago Fire. Waterman is also part of a big sporting family: he is married to Carli Grosso, sister of Canada midfielder Julia Grosso, who is engaged to the Houston Astros baseball star, Jeremy Peña."}, special: "History maker" },
  { number: 13, name: 'Derek Cornelius', position: 'DF', age: 28, club: 'Marseille', bio: {"es":"Cornelius, delantero hasta su adolescencia, todavía tiene sólidos instintos de ataque, como lo demostró cuando anotó un excelente tiro libre de larga distancia en la victoria por 1-0 en un amistoso contra Gales el año pasado. “Esta semana estuve trabajando en ello durante el entrenamiento”, dijo. \"Me sentí confiado y estaba en un buen espacio, logré un buen contacto y entró\". Sin embargo, normalmente se le conoce como un central de la vieja escuela, que no tiene reparos en lanzarse delante o hacia el balón para proteger el área. Con un currículum que incluye paradas en Serbia, Alemania, Canadá, Grecia, Suecia, Francia y ahora Escocia, Cornelius aporta mucha experiencia, pero también ha tenido una temporada difícil con los Rangers, su cesión se vio socavada por problemas de lesiones. Esperará demostrar que los escépticos están equivocados junto a Moïse Bombito en el corazón de la defensa de Canadá.","en":"A striker until his teenage years, Cornelius still has some solid attacking instincts, as shown when he scored a fine long-range free-kick in a 1-0 friendly win against Wales last year. “I was working on it in training this week,” he said. “I felt confident and was in a good space, and I got good contact and it went in.” Typically, though, he’s known as an old-school centre-back, not shy to throw himself in front of, or at the ball in order to protect the box. With a CV that includes stops in Serbia, Germany, Canada, Greece, Sweden, France and now Scotland, Cornelius brings plenty of experience, but has also had a difficult season with Rangers, his loan spell undermined by injury problems. He will be hoping to prove the doubters wrong alongside Moïse Bombito in the heart of Canada’s defence."}, special: "Old-school" },
  { number: 15, name: 'Moïse Bombito', position: 'DF', age: 26, club: 'Nice', bio: {"es":"En el último Mundial Bombito tenía 22 años y veía Canadá por televisión desde su campus universitario. Ahora es la piedra angular de Canadá, la clave que permite a Jesse Marsch utilizar su sistema de alta presión. Bombito, un jugador tardío, era extremo hasta que un entrenador sugirió que su ritmo, técnica y físico lo convertirían en un defensa central de primer nivel. Gracias a ese cambio de posición, tuvo un rápido ascenso a la MLS, obteniendo una primera convocatoria canadiense en 2023. Sus actuaciones en la Copa América 2024 le valieron un gran paso a la Ligue 1 con el Niza. “Elegí Niza por el factor humano”, dijo Bombito el año pasado. \"Sabes, muchos clubes importantes buscan un jugador que se desempeñe bien. Pero no les importa su mentalidad, sus antecedentes o lo que hace su familia. Pero sentí que la organización aquí se centró en quién soy... Todo esto sucedió muy rápido para mí, comencé a jugar a nivel profesional cuando tenía 23 años... este club sabe que me tomará tiempo adaptarme. Estoy muy orgulloso de mi elección\". Bombito, que lleva el número 64 en homenaje al autobús del área de Montreal que solía tomar para ir a la escuela, se está recuperando actualmente de una fractura de tibia que sufrió en octubre. Marsch, que dice que el central \"puede ser nuestro mejor jugador y es el futuro capitán de este equipo\", espera poder ganar su carrera de preparación física para la Copa del Mundo.","en":"At the last World Cup Bombito was 22, watching Canada on TV from his college campus. Now he is Canada’s rock at the back, the key who allows Jesse Marsch to play his high-pressing system. A late bloomer, Bombito was a winger until a coach suggested his pace, technique and physicality would make him a top central defender. Thanks to that positional shift he had a rapid rise to the MLS, earning a first Canadian call-up in 2023. His displays at the 2024 Copa América earned him a big move to Ligue 1 with Nice. “I chose Nice because of the human factor,” Bombito said last year. “You know, many top clubs look for a player who performs well. But they don't care about their mentality, their background, or what their family does. But I felt like the organisation here focused on who I am … This has all happened very quickly for me, I started playing at professional level when I was 23 years old … this club knows it will take time for me to adapt. I am very proud of my choice.” Bombito, who wears the number 64 in tribute to the Montreal-area bus he used to take to school, is currently recovering from a tibia fracture sustained in October. Marsch, who says the centre-back “can be our best player and is a future captain of this team,” is hoping he can win his fitness race for the World Cup."} },
  { number: 19, name: 'Alphonso Davies', position: 'DF', age: 26, club: 'Bayern Munich', bio: {"es":"Cuando Davies mueve sus pies, vuela, y ciertamente se sintió como si tuviera alas cuando saltó para anotar el primer gol de Canadá en la Copa Mundial de 2022. \"Cuando corrí hacia el banderín de esquina, miré a mi izquierda y vi a todos mis compañeros corriendo hacia mí. Cuando todos me rodearon, muchos jugadores agarraron mi camiseta, me empujaron, me empujaron. Liam Millar me dio un cabezazo en un momento, estaba muy emocionado. Ambos nos miramos el uno al otro. el otro y comencé a reír.\" También causó un gran impacto en las gradas: sus padres, que habían huido de la guerra civil en Liberia a Ghana, donde Davies nació en un campo de refugiados, antes de encontrar refugio seguro en Canadá, estaban en el estadio mirando. \"Me dijeron lo orgullosos que estaban de mí y cuando marqué el gol, mi madre lloró un poco. Mis padres son personas de pocas palabras, en realidad no dicen demasiado. Pero realmente se notaba en sus caras\". En 2018, cuando tenía 17 años, pronunció un discurso sobre sus antecedentes ante los delegados de la FIFA en Moscú como parte de la candidatura de Canadá para albergar esta Copa del Mundo. Luego, Davies se unió al Bayern de Múnich procedente de los Vancouver Whitecaps, convirtiéndose en uno de los mejores laterales izquierdos del mundo y ganando todo lo que estuvo a su alcance en el camino.","en":"When Davies moves his feet, he flies – and it certainly felt like he had wings when he leapt to head home Canada’s first-ever World Cup goal in 2022. “When I ran to the corner flag, I looked to my left and I just saw all my teammates running towards me. When they all came around me, a lot of players were grabbing my jersey, pushing me, shoving me. I had Liam Millar headbutt me at one point, he was so excited. We both looked at each other and started laughing.\" It made a big impact in the stands, too: his parents, who had fled the civil war in Liberia to Ghana, where Davies was born in a refugee camp, before finding safe haven in Canada, were in the stadium watching. “They told me how proud they are of me and when I scored the goal, my mother teared up a bit. My parents are people of few words, they don't really say too much. But it really showed on their faces.” Back in 2018, aged 17, he gave a speech about his background to Fifa delegates in Moscow as part of the Canadian bid to host this World Cup. Davies then joined Bayern Munich from Vancouver Whitecaps, blossoming into one of the world’s best left-backs, and winning everything available to him along the way."}, special: "Superstar" },
  { number: 22, name: 'Richie Laryea', position: 'DF', age: 30, club: 'Toronto FC', bio: {"es":"Es un cliché pero encaja perfectamente con Laryea: lo deja todo en el campo, cada vez que juega. No importa si está corriendo hacia adelante, quedando atrapado en una entrada o dando un paso adelante para un compañero de equipo, Laryea lo hace al 100%, jugando en el borde sin cruzar la línea. \"Cuando las cosas se vuelven hostiles, me pongo aún mejor\", dice. “Entro y rodeo la línea, luego me quedo allí y no la paso”. Una seria amenaza de ataque, el hombre del Toronto FC se especializa en centros bajos y faltas ganadoras, pero también es un defensor capaz de 1 contra 1 que puede jugar tanto como lateral izquierdo como derecho. Podría decirse que fue el mejor jugador de Canadá en 2025 y su forma le ha permitido a Alphonso Davies operar más adelante en la selección nacional. Laryea tuvo una etapa fallida en Nottingham Forest, firmó en 2022 pero regresó a Toronto después de seis meses, inicialmente cedido. \"No hay nada negativo. Hay muchos aspectos positivos\", dijo sobre la medida de Forest. \"Creo que me ha ayudado mucho a crecer como jugador y como persona, especialmente fuera del campo. Otras personas pueden tener perspectivas diferentes... tal vez la gente pensaba que yo era infeliz o miserable, pero creo que era todo lo contrario\".","en":"It’s a cliché but it fits Laryea perfectly: he leaves everything on the pitch, every time he plays. It doesn’t matter if he’s making an overlapping run forward, getting stuck into a tackle or stepping up for a teammate, Laryea does it at 100%, playing on the edge without crossing the line. “When it gets hostile, I get even better,” he says. “I get in and around the line, then I stay there and don’t go past it.” A serious attacking threat, the Toronto FC man specialises in low crosses and winning fouls, but is also a capable 1v1 defender who can play both at left and right-back. He was arguably Canada’s best player in 2025 and his form has allowed Alphonso Davies to operate further forward for the national team. Laryea had an unsuccessful spell at Nottingham Forest, signing in 2022 but returning to Toronto after six months, initially on loan. “No negatives. A lot of positives,” he said about the Forest move. “I think it's helped me a lot to grow as a player and a person, especially off the field. Other people might have different perspectives … maybe people thought I was unhappy or miserable, but I think it was the opposite.\""} },
  { number: 23, name: 'Niko Sigur', position: 'DF', age: 22, club: 'Hajduk Split', bio: {"es":"La mayoría de los jugadores conocen su posición preferida, pero Sigur, que ha jugado como mediocampista defensivo y lateral para el club y la selección, mantiene abiertas sus opciones. \"Si el entrenador confía en ti en esas [diferentes] posiciones\", dijo, \"entonces tienes una pequeña ventaja sobre los demás jugadores\". Sigur, que tiene doble ciudadanía canadiense y croata, debería ser una navaja suiza muy útil como jugador para Jesse Marsch este verano. Estuvo fuertemente vinculado con Celtic y Wolves en la ventana de enero, y podría ser el foco de más especulaciones una vez que termine la Copa del Mundo. Sigur dijo a The Athletic el año pasado: \"Creo que a Hajduk le conviene venderme en algún momento. Es cuestión de tiempo. Y creo que estoy preparado para ello. Quiero que tenga sentido. No quiero ir a un gran club e ir cedido o sentarme en el banquillo. Quiero jugar\".","en":"Most players know their preferred position but Sigur, who has played as a defensive midfielder and full-back for club and country, is keeping his options open. “If the coach trusts you in those [different] positions,” he said, “then you have a bit of an advantage over other players.” Sigur, who holds dual citizenship of Canada and Croatia, should be a very handy Swiss Army knife of a player for Jesse Marsch this summer. He was heavily linked with Celtic and Wolves in the January window, and could be the focus of more speculation once the World Cup is over. Sigur told The Athletic last year: “I think it’s in Hajduk’s best interest to sell me at some point. It’s a matter of time. And I think I’m ready for it. I want it to make sense. I don’t want to go to a huge club and go on loan or sit on the bench. I want to play.”"} },
  // Volantes
  { number: 6, name: 'Mathieu Choinière', position: 'MF', age: 26, club: 'Los Angeles FC', bio: {"es":"No es frecuente que un jugador viva el sueño de convertirse en una estrella con el equipo de su ciudad natal, pero Mathieu Choinière lo experimentó con el CF Montréal, ganando dos lugares para el Juego de Estrellas de la MLS durante sus siete temporadas en el club. Su consistencia no pasó desapercibida. Dio el salto al fútbol europeo con el Grasshoppers en 2024 y luego regresó a la MLS con el club matriz del equipo suizo, Los Angeles FC, el año pasado. El copresidente del LAFC, John Thorrington, elogió su “experiencia, inteligencia, autoridad tranquila y ventaja competitiva... también estamos entusiasmados con la oportunidad de Mathieu de representar a su país en el escenario más grande y orgullosos de apoyarlo en esa ambición”. En un equipo de Los Ángeles lleno de nombres estelares, Choinière encaja perfectamente con su ética de trabajo y su versatilidad, ya que jugó como lateral y extremo en Montréal antes de instalarse en el mediocampo central. También es uno de los mejores lanzadores de jugadas a balón parado de Canadá.","en":"It’s not often that a player gets to live out the dream of becoming a star player with their hometown team, but Mathieu Choinière experienced that with CF Montréal, earning two MLS All-Star game places during his seven seasons at the club. His consistency didn’t go unnoticed. He made the leap into European football with Grasshoppers in 2024, then moved back to MLS with the Swiss side’s parent club, Los Angeles FC, last year. LAFC’s co-president, John Thorrington, praised his “experience, intelligence, calm authority and competitive edge … we’re also excited about the opportunity for Mathieu to represent his country on the biggest stage and proud to support him in that ambition.” In an LA team filled with star names, Choinière fits in perfectly with his work ethic and his versatility, having played as a wing-back and winger for Montréal before settling into central midfield. He is also one of Canada’s best set-piece takers."}, special: "Set-piece specialist" },
  { number: 7, name: 'Stephen Eustáquio', position: 'MF', age: 29, club: 'Porto', captain: true, bio: {"es":"Mientras otros pueden presumir de ser la cara de este equipo canadiense, Eustáquio es sin duda el latido del corazón. Líder apasionado, algunas de sus mejores actuaciones con el club y la selección se produjeron en los escenarios más importantes, como lo demostró con el gigante portugués Porto, donde ganó múltiples trofeos. Un incansable corredor de caja a caja, aporta una enorme versatilidad, igualmente hábil como atacante, como progresador de balón, como bloqueador defensivo profundo e incluso como central: el sueño de un entrenador. Nacido en Ontario, no lejos de la frontera con Estados Unidos, Eustáquio se mudó con sus padres portugueses a Portugal cuando tenía siete años, donde comenzó su andadura en el fútbol profesional. Se mudó del Oporto al LAFC en calidad de préstamo en febrero de este año, añadiendo fuerza a su equipo repleto de estrellas. Su compañero de equipo de Canadá, Richie Laryea, dice que no se puede subestimar la importancia de Eustáquio para la selección nacional: \"Él hace mucho del trabajo sucio que la gente realmente no reconoce\".","en":"While others can claim to be the face of this Canadian team, Eustáquio is undoubtedly the heartbeat. A passionate leader, some of his best performances for club and country have come on the biggest stages, as he showed with Portuguese giants Porto, where he won multiple trophies. A tireless box-to-box runner, he brings huge versatility, equally adept as a box-crasher, a ball-progresser, a deep-lying defensive blocker, and even a centre-back – a coach's dream. Born in Ontario, not far from the US border, Eustáquio moved with his Portuguese parents back to Portugal when he was seven, where he began his journey into professional football. He moved from Porto to LAFC on loan in February this year, adding strength to their star-studded team. Canada teammate Richie Laryea says Eustáquio’s importance to the national side cannot be overstated: “He does a lot of the dirty work that people don't really recognise.”"}, special: "A coach's dream" },
  { number: 8, name: 'Ismaël Koné', position: 'MF', age: 23, club: 'Sassuolo', bio: {"es":"En su mejor momento, Koné es un espectáculo digno de contemplar, deslizándose por el medio campo, encontrando espacios y dejando a los defensores a su paso. Tiene la capacidad de iluminar los partidos, como lo demostró en un amistoso entre Canadá y Francia en 2024, cuando destacó a pesar de estar rodeado de campeones de la Copa del Mundo. Nacido en Costa de Marfil, se mudó con su madre a Montreal a los siete años y pronto se hizo un nombre cuando era adolescente en el equipo de la MLS de la ciudad. Desde allí, Koné fue trasladado rápidamente a Europa, primero a Watford en 2022 y luego a Marsella dos años después. Se unió al Sassuolo el año pasado, inicialmente cedido antes de que la mudanza se hiciera permanente en febrero. Puede que su voz sea suave, pero Koné tiene un espíritu competitivo feroz y está decidido a mejorar su consistencia. El año pasado, Jesse Marsch lo calificó como un trabajo en progreso. \"Le dejé muy claro que todos creemos en su talento\", dijo Marsch, \"pero necesitamos perfeccionarlo como jugador de fútbol, ​​en la disciplina y concentración de lo que hace en el campo... Definitivamente no estoy tratando de limitar su talento y su creatividad, pero estoy tratando de agregar más disciplina táctica\".","en":"At his best, Koné is a sight to behold, gliding across midfield, finding space and leaving defenders in his wake. He has the ability to light up games, as he showed in a 2024 friendly between Canada and France when he stood out despite being surrounded by World Cup winners. Born in Côte d’Ivoire, he moved with his mother to Montreal aged seven and was soon making his name as a teenager with the city’s MLS side. Koné was fast-tracked from there to Europe, first to Watford in 2022, then Marseille two years later. He joined Sassuolo last year, initially on loan before the move was made permanent in February. He might be softly spoken, but Koné has a fierce competitive spirit and is determined to improve his consistency. Last year, Jesse Marsch labelled him a work in progress. “I’ve made it very clear to him that we all believe in his talent,” said Marsch, “but we need to refine him as a soccer player, on the discipline and concentration of what he does on the pitch … I’m definitely not trying to limit his talents and his creativity, but I’m trying to add more tactical discipline.”"}, special: "Going places" },
  { number: 14, name: 'Jacob Shaffelburg', position: 'MF', age: 26, club: 'Los Angeles FC', bio: {"es":"No es frecuente que el cabello de un jugador gane su propio apodo, pero los mechones dorados de Shaffelburg eran conocidos como el “Tennessee Waterslide” en su club anterior, Nashville SC, un guiño a cómo el salmonete fluye detrás de él cuando corre. Puede que su juego no sea tan llamativo como su cabello, pero sigue siendo un corredor eficaz e incansable que sabe cómo golpear la pelota con potencia y técnica. Nacido en Nueva Escocia, Shaffelburg está en forma para estar a la altura del momento en el gran escenario, ya que brilló con Canadá en la Copa América 2024. Se mudó a Hollywood con el LAFC en diciembre pasado y llega a este Mundial de muy buen humor. Shaffelburg dice que jugar con Jesse Marsch le sienta bien: \"El estilo de juego simplemente me queda bien. Me dice que entre y corra detrás, y eso es todo lo que quiero hacer en general. Es lo que me gusta\".","en":"It’s not often that a player’s hair earns its own nickname, but Shaffelburg’s golden locks were known as the “Tennessee Waterslide” at his previous club Nashville SC, a nod to how the mullet flows behind him when he’s sprinting. His game may not be as flashy as his hair, but he is still an effective, tireless runner who knows how to strike the ball with power and technique. Born in Nova Scotia, Shaffelburg has form for rising to the moment on the big stage, having shone for Canada at the 2024 Copa América. He moved to Hollywood with LAFC last December, and arrives at this World Cup in a positive mood. Shaffelburg says playing under Jesse Marsch suits him: “The style of play just kind of fits me. He tells me just to get in and run behind, and that's all I want to do in general. It's right up my alley.”"} },
  { number: 21, name: 'Jonathan Osorio', position: 'MF', age: 33, club: 'Toronto FC', bio: {"es":"Osorio, un hombre poco común en un solo club en el fútbol moderno, ha estado con el equipo de su ciudad natal, Toronto FC, durante 14 temporadas, ganando una Copa MLS, Supporters’ Shield y tres Campeonatos Canadienses. Un mediocampista revoltoso que chocaba el área en su juventud, ha marcado algunos goles importantes para el club y el país, como su descarado tacón contra Tigres durante el camino a la final de la Copa de Campeones de la Concacaf 2018, y su gol crucial para Canadá contra México en el Estadio Azteca durante la clasificación para la Copa del Mundo 2022. Una de las verdaderas caras del fútbol canadiense, y a punto de cumplir 100 partidos internacionales, aporta una gran cantidad de conocimientos al equipo de este verano, y Jesse Marsch lo elogió antes del torneo por su “intensidad, cobertura del terreno, ser difícil de enfrentar, ser un dictador del ritmo del juego... La experiencia de Oso, su estabilidad, su mentalidad, su personalidad: aporta mucho al grupo”.","en":"A rare one-club man in the modern game, Osorio has been with his hometown team, Toronto FC, for 14 seasons, winning an MLS Cup, Supporters’ Shield and three Canadian Championships. A rambunctious box-crashing midfielder in his younger days, he has scored some big goals for club and country, such as his cheeky backheel against Tigres during the run to the 2018 Concacaf Champions Cup final, and his crucial goal for Canada against Mexico at the Estadio Azteca during World Cup 2022 qualifying. One of the true faces of Canadian soccer, and closing in on 100 caps, he brings a wealth of knowhow to this summer’s squad, with Jesse Marsch praising him pre-tournament for his “intensity, covering the ground, being hard to play against, being a dictator of the rhythm of the game … Oso’s experience, his stability, his mentality, his personality – he brings so much to the group.”"} },
  { number: 25, name: 'Nathan-Dylan Saliba', position: 'MF', age: 21, club: 'Anderlecht', bio: {"es":"El progreso de Saliba cuando era joven con el CF Montréal de su ciudad natal fue rápido. A los 12 meses de su avance en el club, hizo su debut en Canadá, fue nombrado uno de los mejores sub-22 de la MLS y luego se mudó al equipo belga Anderlecht el año pasado por una tarifa no revelada, y el Montréal retuvo una cláusula de venta. “Sus cualidades son una locura”, dijo entonces su excompañero Ismaël Koné. \"Es uno de esos jugadores que no puedo esperar a florecer. Porque tiene mucho que mostrar, muchos regalos que dar. Y no puedo esperar a que ustedes vean dónde terminará y qué tan grande será para el país\". También hubo muchos elogios por parte de Jesse Marsch: “Tiene una muy buena combinación de inteligencia, atletismo, habilidad técnica, conciencia táctica, responsabilidad, compromiso con el juego, buen ojo para buenas jugadas de ataque... realmente creemos que puede ser un jugador importante para nosotros”. Los padres de Saliba son ambos haitianos y él habla tres idiomas: francés, inglés y criollo haitiano.","en":"Saliba’s progress as a youngster with hometown side CF Montréal was rapid. Within 12 months of his club breakthrough he made his Canada debut, was named one of the best Under-22s in MLS, and then moved to Belgian side Anderlecht last year for an undisclosed fee, with Montréal retaining a sell-on clause. “His qualities are insane,” former teammate Ismaël Koné told said at the time. “He’s one of those players that I can’t wait to flourish. Because he has so much to show, a lot of gifts to give. And I just can’t wait for you guys to see where he’s going to end up, and how big he’s going to be for the country.” There was plenty of praise, too, from Jesse Marsch: “He has a really good combination of intelligence, athleticism, technical ability, tactical awareness, responsibility, commitment to the game, a good eye for good attacking plays … we really believe he can be an important player for us.” Saliba’s parents are both Haitian and he speaks three languages: French, English and Haitian Creole."} },
  // Delanteros
  { number: 9, name: 'Cyle Larin', position: 'FW', age: 31, club: 'Mallorca', bio: {"es":"Pase lo que pase este verano, Larin siempre será un héroe de culto en Canadá por sus actuaciones durante el ciclo de clasificación de 2022, cuando anotó 13 goles en 16 partidos, ayudando a Canadá a alcanzar su primera Copa del Mundo desde 1986. Conocido por sus movimientos inteligentes en el área y sus primeros remates, puede ser un verdadero desafío, como lo demostró durante un breve período en el Real Valladolid, donde los fanáticos acuñaron el término \"Larinísimo\". Jesse Marsch dijo en marzo que la cesión de Larin a Southampton era el momento perfecto. \"Es exactamente lo que necesitaba. Está jugando de manera sobresaliente, ha tenido un gran impacto y llegará a la Copa del Mundo en buena forma, que es exactamente lo que necesitamos. No podría estar más emocionado por Cyle en este momento\". Cuando fichó por los Saints, Larin, que ya había jugado en Estados Unidos, Canadá, Turquía, Bélgica, España y Holanda, dijo en su sitio web que jugar en Inglaterra \"siempre ha sido una picazón. El estilo de juego, la forma de jugar al fútbol en Inglaterra es algo que siempre quise vivir y respirar\".","en":"Whatever happens this summer, Larin will forever be a cult hero in Canada for his displays during the 2022 qualifying cycle when he scored 13 goals in 16 games, helping Canada reach their first World Cup since 1986. Known for his smart movement in the box and first-time finishing, he can be a real handful as he showed during a brief spell at Real Valladolid where fans coined the term “Larinisimo”. Jesse Marsch said in March that Larin’s loan to Southampton was perfect timing. “It’s exactly what he needed. He's playing outstanding, he’s made a huge impact and will come into the World Cup in form, which is exactly what we need. I couldn’t be more excited for Cyle right now.\" When he signed for the Saints, Larin, who had already played in the US, Canada, Turkey, Belgium, Spain and the Netherlands, told their website that playing in England “has always been an itch. The style of play, the way of football in England is something I’ve always wanted to live and breathe.”"}, special: "Cult hero" },
  { number: 10, name: 'Jonathan David', position: 'FW', age: 26, club: 'Juventus', bio: {"es":"\"Es el jugador más inteligente que he entrenado\", dice Jesse Marsch. David es realmente un delantero cerebral, un rematador de dos pies con el ritmo de trabajo de un mediocampista. Ha recorrido un largo camino desde un joven tímido que jugaba en la capital canadiense, Ottawa, hasta convertirse en una estrella mundial con la Juventus. Fue su audaz apuesta cuando era adolescente al fichar por el Gent belga en lugar de quedarse en Canadá lo que aceleró su camino hacia la cima. Luego, David se mudó al Lille de la Ligue 1 e inmediatamente jugó su papel en su sorpresiva victoria por el título 2020-21, antes de convertirse en uno de los mejores delanteros de Europa durante su media década en Francia. Habiendo estado fuertemente vinculado con un traslado a Inglaterra, David dijo a The Guardian el año pasado: \"Para mí, al ver la Premier League, la mayor diferencia es simplemente la intensidad. El juego siempre tiene un ritmo alto, siempre 100% de ida y vuelta durante 90 minutos\". Conocido como El Hombre de Hielo por su naturaleza tranquila e imperturbable, David se ve a sí mismo como \"alguien que siempre está tranquilo. Como delantero, alguien en quien se confía para marcar goles, creo que esa calidad es útil\". Después de un comienzo lento en Turín, el delantero ganó más minutos de juego con Luciano Spalletti a medida que avanzaba la temporada.","en":"“He's the smartest player I've ever coached,” says Jesse Marsch. David really is a cerebral striker, a two-footed finisher with the workrate of a midfielder. He has undergone quite the journey from timid youngster playing in the Canadian capital, Ottawa, to becoming a global star with Juventus. It was his bold gamble as a teenager to sign with Belgian side Gent instead of staying in Canada that accelerated his road to the top. David then moved to Ligue 1 side Lille and immediately played his part in their surprise 2020-21 title win, before blossoming into one of the best strikers in Europe across his half-decade in France. Having been heavily linked with a move to England, David told The Guardian last year: “For me, watching the Premier League, the biggest difference it’s just the intensity. The game is always at a high-end tempo, always 100% back and forth for 90 minutes.” Known as The Iceman for his cool, unflappable nature, David sees himself as “someone that’s always calm. As a striker, someone who’s relied on to score goals, I think that quality comes in handy.” After a slow start in Turin, the striker earned more game time under Luciano Spalletti as the season unfolded."}, special: "Main goalscorer" },
  { number: 11, name: 'Liam Millar', position: 'FW', age: 26, club: 'Hull City', bio: {"es":"Criado en la academia del Liverpool, Millar ha desarrollado una carrera sólida, con préstamos en Kilmarnock y Charlton seguidos de un período decisivo en Suiza con el Basilea. Regresó a Inglaterra con Preston en calidad de préstamo en 2023, luego fichó por Hull con un contrato permanente en agosto de 2024. Millar sufrió una lesión del ligamento cruzado anterior en octubre, y necesitó cirugía y un largo período de recuperación, pero recuperó su fuerza y ​​forma gracias a \"trabajar mi trasero durante 12 meses\". Millar proviene de una familia de futbolistas: su abuelo Malcolm jugó en el Sunderland, mientras que su padre Alan jugó en el Charlton. Alan pasó a trabajar en la industria del cine y la televisión como electricista en Game of Thrones, Peaky Blinders y X-Men, mientras que su madre, Jo-Ann, trabajó como maquilladora en películas como Resident Evil, Suicide Squad y Dune.","en":"Raised in Liverpool’s academy, Millar has gone on to build a solid career, with loans at Kilmarnock and Charlton followed by a breakthrough period in Switzerland with Basel. He moved back to England with Preston on loan in 2023, then signed for Hull on a permanent deal in August 2024. Millar sustained an ACL injury that October, needing surgery and a lengthy recovery period, but regained his strength and form thanks to “working my backside off for 12 months”. Millar is from a football family: his grandad Malcolm played for Sunderland, while his dad Alan turned out for Charlton. Alan went on to work in the TV and film industry as an electrician on Game of Thrones, Peaky Blinders, and X-Men, while mum Jo-Ann worked as a make-up artist on movies such as Resident Evil, Suicide Squad and Dune."} },
  { number: 12, name: 'Tani Oluwaseyi', position: 'FW', age: 26, club: 'Villarreal', bio: {"es":"Oluwaseyi, un verdadero jugador de equipo, tiene un gran motor y siempre corre tan duro para ayudar a defender como lo hace cuando ataca. Un tardío que no se convirtió en un habitual de la MLS hasta los 23 años, su ética de trabajo y su habilidad para encontrarse abierto en el área en los momentos perfectos llevaron a acuñar el término \"Tani Time\" en Minnesota United. Sus actuaciones allí le valieron un gran traslado al Villarreal el año pasado, donde continuó desarrollando su juego completo, diciendo: \"Jugar y entrenar en España ya me ha convertido en un jugador más inteligente\". Nacido en Nigeria, Oluwaseyi se mudó con su familia a Mississauga, Canadá, a la edad de 10 años. El año pasado habló sobre lo que significaría representar a Canadá en una Copa Mundial: \"Para ser honesto, creo que hasta que eso suceda, hasta que escuchemos el himno [nacional], no se sentirá real. Pero estoy muy emocionado por ello\".","en":"A real team player, Oluwaseyi has a great engine, always running as hard to help defend as he does when attacking. A late bloomer who didn’t become an MLS regular until he was 23, his work ethic and knack for finding himself open in the box at perfect moments led to the coining of the term “Tani Time” at Minnesota United. His performances there earned a big move to Villarreal last year where he continued to develop his all-round game, saying: “Playing and training in Spain has already made me a smarter player.” Born in Nigeria, Oluwaseyi moved with his family to Mississauga, Canada at the age of 10. He spoke last year about what it would mean to represent Canada at a World Cup: “To be honest, I think until it happens, until we hear the [national] anthem, it won’t feel real. But I’m really excited for it.”"} },
  { number: 17, name: 'Tajon Buchanan', position: 'FW', age: 26, club: 'Villarreal', bio: {"es":"En un mundo donde los extremos modernos a veces pueden parecer robóticos, Buchanan es de la vieja escuela: un atacante impredecible al que le encanta enfrentarse a los defensores usando un arsenal de fintas corporales, pasos por encima y movimientos rápidos. Un tardío que surgió del sistema universitario de la NCAA, se hizo un nombre con el New England Revolution de la MLS a partir de 2019. Buchanan desarrolló tan bien el lado defensivo de su juego que jugó como lateral para el Club Brugge y lateral en el Inter en la Serie A. Sin embargo, siempre se ha sentido más cómodo en el lateral, y un traslado a España con el Villarreal el año pasado le permitió regresar a esa posición, en beneficio del club y del país. Buchanan, un personaje tranquilo y serio, ha tenido que mostrar una verdadera resiliencia para progresar en el juego. Su padre murió cuando él tenía sólo siete años y dejó su casa a los 15 para mudarse a Colorado con la familia de su amigo. \"Soy más introvertido. Todo me resulta natural\", dijo a The Athletic. “Desde que era adolescente he estado lejos de casa, solo, tratando de perseguir mi sueño”.","en":"In a world where modern wingers can sometimes look robotic, Buchanan is old-school: an unpredictable attacker who loves to take on defenders using an arsenal of body feints, stepovers and flicks. A late bloomer who emerged from the NCAA college system, he made his name with MLS side New England Revolution from 2019. Buchanan developed the defensive side of his game so well that he played as a full-back for Club Brugge and wing-back at Inter in Serie A. He has always been most comfortable on the wing, though, and a move to Spain with Villarreal last year allowed him to return to that position, to the benefit of club and country. A quiet, serious character, Buchanan has had to show real resilience to progress in the game. His father died when he was just seven, and he left home at 15 to move to Colorado with his friend’s family. “I’m more introverted. It all comes naturally to me,” he told The Athletic. “Since I was a teenager, I’ve been away from home, alone, trying to chase my dream.”"}, special: "Unpredictable" },
  { number: 20, name: 'Ali Ahmed', position: 'FW', age: 25, club: 'Norwich City', bio: {"es":"Cuando era joven, Ahmed falló en las pruebas en Enfield Town, Cheshunt y Tooting & Mitcham. Ahora es parte de un equipo de la Copa del Mundo y aporta una enorme versatilidad a la combinación de Canadá. Se abrió paso en Vancouver Whitecaps durante tres años llamativos en la MLS, donde jugó como lateral, lateral, mediocampista central y mediocampista ofensivo antes de especializarse como extremo, un movimiento que lo ayudó a convertirse en uno de los mejores talentos de la liga y a conseguir una transferencia a Norwich en enero. Ahmed es un regateador eficaz, aunque poco ortodoxo, al que le gusta utilizar fintas corporales, un guiño a su gran amor por el baloncesto. Dice que la vida en Inglaterra le ha añadido valor a su juego: \"Antes de llegar al campeonato, todas las personas con las que hablé hablaban de la intensidad y el aspecto físico del mismo y estuvo a la altura de cada palabra. Creo que eso es bueno para mí, es un área que quiero mejorar\". Reflexionando sobre su regreso a Inglaterra, cinco años después de esa serie de pruebas en clubes que no pertenecen a la liga, dijo: \"El fútbol es una locura y cada jugador tiene su propio camino para llegar a donde está. Pero si me hubieran dicho entonces que volvería dentro de cinco años jugando en la Championship, no sé si lo habría creído\".","en":"As a youngster, Ahmed failed trials at Enfield Town, Cheshunt and Tooting & Mitcham. Now he’s part of a World Cup squad, and brings huge versatility to Canada’s mix. He broke through at Vancouver Whitecaps during three eye-catching years in MLS where he featured at full-back, wing-back, central midfielder and attacking midfielder before specialising as a winger – a move which helped him blossom into one of the league’s best talents, and earn a transfer to Norwich in January. Ahmed is an effective if unorthodox dribbler who likes to use body feints – a nod to his strong love for basketball. He says that life in England has added grit to his game: “Before I came into the Championship, everyone I spoke to talked about the intensity and the physicality of it and it has lived up to every single word. I think that's good for me – it's an area I want to improve.” Reflecting on his return to England, five years after that series of trials at non-league clubs, he said: “Football is crazy and every player has their own journey to get to where they are. But if you told me then that I would be back in five years playing in the Championship, I don't know if I would have believed it.”"} },
  { number: 24, name: 'Promise David', position: 'FW', age: 25, club: 'Union Saint-Gilloise', bio: {"es":"Sin relación con Jonathan, Promise David se ha convertido en el favorito de los fanáticos gracias a su sonrisa, personalidad y su altura de 1,96 m. Un susto de lesión puso en duda su participación este verano, pero se recuperó para ganarse un lugar en el equipo de Marsch, y se lo merece por su empuje y compromiso. Como aprendió un desafortunado defensa de Amberes la temporada pasada, puedes intentar literalmente arrancarle la camiseta a David y eso no le impedirá anotar. A pesar de su tamaño, David está lejos de ser un delantero centro unidimensional, y a menudo se gana elogios por sus pies hábiles y su tacto suave, lo que le ha permitido acumular un catálogo de goles impresionante y variado. Desde que llegó a Bélgica procedente de la liga estonia, ha desarrollado su juego completo, sin perder su instintivo toque goleador, y ayudó a llevar al Union Saint-Gilloise a su primer título de liga en 90 años. Se le ha vinculado con varios clubes de la Premier League, pero su equipo actual querrá mucho dinero.","en":"No relation to Jonathan, Promise David has become a fan favourite thanks to his smile, personality and 1.96m frame. An injury scare put his involvement this summer in doubt, but he recovered to earn his place in Marsch’s squad, and deserves it for his drive and commitment. As one unfortunate Antwerp defender learned last season, you can try to literally rip the shirt off David’s back and that still won’t stop him from scoring. Despite his size, David is far from a one-dimensional centre forward, often earning praise for his deft feet and soft touch, which has allowed him to rack up an impressive and varied goal catalogue. Since arriving in Belgium from the Estonian league he has developed his all-round game, without losing his instinctive scoring touch, and helped lead Union Saint-Gilloise to their first league title in 90 years. He has been linked with several Premier League clubs, but his current side will want big money."} },
  { number: 26, name: 'Marcelo Flores', position: 'FW', age: 23, club: 'Tigres UANL', bio: {"es":"Ha sido descartado por una lesión del ligamento anterior cruzado. El reemplazo aún no se ha anunciado.","en":"Has been ruled out with an ACL injury. Replacement not yet announced."} },
];

